const dx=(0.9*Math.sin(t*0.41)+0.5*Math.sin(t*0.97+1.6))*18*sc*(0.4+en);
const dy=(0.8*Math.sin(t*0.53+2)+0.5*Math.sin(t*1.19))*16*sc*(0.4+en);
const spin=Math.sin(t*0.31)*0.15*(0.4+en);
const limb=Math.sin(t*1.3)*P.limbs;

let suit=[0,0,96], suit2=[210,10,72], visorc=[P.hue,80,45], visorG=[P.hue,60,90], accent=[15,80,95], ink=[210,20,25], jetc=[30,90,100];
if(sty==='retro'){ suit=[45,25,90]; suit2=[40,30,66]; visorc=[35,80,55]; visorG=[45,60,85]; accent=[0,70,85]; ink=[30,40,25]; }
else if(sty==='neon'){ suit=[P.hue,15,22]; suit2=[P.hue,25,15]; visorc=[(P.hue+140)%360,90,50]; visorG=[(P.hue+140)%360,90,100]; accent=[(P.hue+300)%360,90,100]; ink=[(P.hue+140)%360,90,100]; }
else if(sty==='chrome'){ suit=[210,6,92]; suit2=[210,10,64]; visorc=[200,40,40]; visorG=[190,50,95]; accent=[40,60,95]; ink=[210,20,30]; }
else if(sty==='pixel'){ suit=[0,0,94]; suit2=[210,12,68]; visorc=[P.hue,70,50]; visorG=[P.hue,60,88]; accent=[15,80,92]; ink=[210,25,20]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }
const glow=(sty==='neon');

push();
translate(cx+dx, cy+dy);
rotate(spin);
scale(sc);
noStroke();

// tether cable trailing off
if(P.tether>0.05){ stroke(Cc(accent,90)); strokeWeight(3); noFill();
  beginShape(); vertex(-30,20); for(let i=1;i<=10;i++){ const s=i/10; vertex(-30-s*160, 20+Math.sin(t*0.8+s*6)*24*s*P.tether + s*60);} endShape(); noStroke(); }

// jetpack plume
if(P.jet>0.05){ const pf=0.6+0.4*Math.sin(t*6);
  drawingContext.save(); drawingContext.shadowBlur=20; drawingContext.shadowColor=Cc(jetc,90).toString();
  fill(Cc(jetc, 70*pf)); triangle(-8,44, 8,44, 0, 44+ (30+P.jet*40)*pf); fill(Cc([50,40,100],80*pf)); triangle(-4,44,4,44,0,44+(16+P.jet*20)*pf); drawingContext.restore(); noStroke(); }

// backpack
fill(Cc(suit2,100)); rect(-20,-6,40,44,6);

// limbs (arms + legs float)
stroke(Cc(suit,100)); strokeWeight(13); strokeCap(ROUND);
push(); translate(-22,4); rotate(-0.5-limb*0.4); line(0,0,0,30); pop();
push(); translate(22,4); rotate(0.5+limb*0.4); line(0,0,0,30); pop();
push(); translate(-12,40); rotate(-0.2+limb*0.3); line(0,0,0,34); pop();
push(); translate(12,40); rotate(0.2-limb*0.3); line(0,0,0,34); pop();
noStroke();
// hands/boots
fill(Cc(suit2,100)); circle(-22+Math.sin(-0.5-limb*0.4)*30, 4+Math.cos(-0.5-limb*0.4)*30, 12); // approx not critical

// torso
fill(Cc(suit,100)); rect(-24,-6,48,52,14);
// chest control panel
fill(Cc(suit2,100)); rect(-14,6,28,20,4); for(let i=0;i<3;i++){ fill(Cc([accent[0]+i*30,80,100], 50+50*Math.sin(t*2+i))); circle(-8+i*8,16,4); }
// helmet
const hr=26;
fill(Cc(suit,100)); circle(0,-22,hr*2+8);
// visor
if(glow){ drawingContext.shadowBlur=16; drawingContext.shadowColor=Cc(visorG,90).toString(); }
fill(Cc(visorc,100)); arc(0,-22,hr*2,hr*2, Math.PI*0.15, Math.PI*0.85, CHORD);
// visor reflection (a little starfield / sun glint)
fill(Cc(visorG, 60)); ellipse(6,-18, hr*0.7, hr*0.5);
