// visor rim
noFill(); stroke(Cc(ink,90)); strokeWeight(2.4); arc(0,-22,hr*2,hr*2, Math.PI*0.13, Math.PI*0.87); noStroke();
// helmet stripe / antenna
fill(Cc(accent,100)); rect(-hr,-40,hr*2,5,2);
stroke(Cc(suit2,100)); strokeWeight(2); line(hr-4,-40, hr+4,-52); noStroke(); fill(Cc(accent,100)); circle(hr+4,-52,5);

blendMode(BLEND); drawingContext.shadowBlur=0;
pop();
